    aeo: [{"pergunta":"Qual é o desafio imediato de Pazolini?","resposta":"Articular apoio na Assembleia Legislativa e estabelecer diálogo institucional com os prefeitos do Espírito Santo."},{"pergunta":"Quantos deputados são de partidos da coligação?","resposta":"Oito dos 30 eleitos: seis do PL e dois do Republicanos."},{"pergunta":"Qual é o papel de Erick Musso?","resposta":"Pazolini indicou que Musso integrará a equipe de transição, segundo informações publicadas por A Gazeta."},{"pergunta":"O que acontecerá agora?","resposta":"A transição deverá definir equipes e iniciar negociações sobre prioridades legislativas e cooperação com os municípios."}],
